                    vil_zz += (al2 * (ai2 * (vgx[(h & 1 ? 2032 : 2224)] - zlzk * vgx[(h & 1 ? 1968 : 2160)]) - 2.0 * (vgx[(h & 1 ? 2000 : 2192)] - zlzk * vgx[(h & 1 ? 1936 : 2128)])) - (h & 1 ? 1.0 : 2.0) * (ai2 * vgx[(h & 1 ? 1712 : 1904)] - 2.0 * vgx[(h & 1 ? 1680 : 1872)])) * S;
                    vjl_zz += (al2 * (aj2 * (vgx[(h & 1 ? 2032 : 2224)] - zjzi * vgx[(h & 1 ? 2016 : 2208)] - zlzk * (vgx[(h & 1 ? 1968 : 2160)] - zjzi * vgx[(h & 1 ? 1952 : 2144)]))) - (h & 1 ? 1.0 : 2.0) * (aj2 * (vgx[(h & 1 ? 1712 : 1904)] - zjzi * vgx[(h & 1 ? 1696 : 1888)]))) * S;
                    vik_zx += Ai * T2;
                    vik_xz += Ak * T0;
                    vjk_zx += Aj * T2;
                    vjk_xz += Ak * T1;
                    vil_zx += Ai * T3;
                    vil_xz += Al * T0;
                    vjl_zx += Aj * T3;
                    vjl_xz += Al * T1;
                    w = dd_cache[(h & 1 ? 3440 : 3344)] * vgx[(h & 1 ? 768 : 832)];
                    S = w * vgx[0];
                    T0 = vgx[2304] * w;
                    T1 = vgx[2320] * w;
                    T2 = vgx[2336] * w;
                    T3 = vgx[2352] * w;
                    Ai = vgx[(h & 1 ? 7424 : 7232)];
                    Aj = vgx[(h & 1 ? 7440 : 7248)];
                    Ak = vgx[(h & 1 ? 7456 : 7264)];
                    Al = vgx[(h & 1 ? 7472 : 7280)];
                    vik_zz += (ak2 * (ai2 * vgx[(h & 1 ? 2288 : 2224)] - 2.0 * vgx[(h & 1 ? 2256 : 2192)]) - (h & 1 ? 2.0 : 1.0) * (ai2 * vgx[(h & 1 ? 2160 : 2096)] - 2.0 * vgx[(h & 1 ? 2128 : 2064)])) * S;
                    vjk_zz += (ak2 * (aj2 * (vgx[(h & 1 ? 2288 : 2224)] - zjzi * vgx[(h & 1 ? 2272 : 2208)])) - (h & 1 ? 2.0 : 1.0) * (aj2 * (vgx[(h & 1 ? 2160 : 2096)] - zjzi * vgx[(h & 1 ? 2144 : 2080)]))) * S;
                    vil_zz += (al2 * (ai2 * (vgx[(h & 1 ? 2288 : 2224)] - zlzk * vgx[(h & 1 ? 2224 : 2160)]) - 2.0 * (vgx[(h & 1 ? 2256 : 2192)] - zlzk * vgx[(h & 1 ? 2192 : 2128)])) - 2.0 * (ai2 * vgx[(h & 1 ? 1968 : 1904)] - 2.0 * vgx[(h & 1 ? 1936 : 1872)])) * S;
                    vjl_zz += (al2 * (aj2 * (vgx[(h & 1 ? 2288 : 2224)] - zjzi * vgx[(h & 1 ? 2272 : 2208)] - zlzk * (vgx[(h & 1 ? 2224 : 2160)] - zjzi * vgx[(h & 1 ? 2208 : 2144)]))) - 2.0 * (aj2 * (vgx[(h & 1 ? 1968 : 1904)] - zjzi * vgx[(h & 1 ? 1952 : 1888)]))) * S;
                    vik_zx += Ai * T2;
                    vik_xz += Ak * T0;
                    vjk_zx += Aj * T2;
                    vjk_xz += Ak * T1;
                    vil_zx += Ai * T3;
                    vil_xz += Al * T0;
                    vjl_zx += Aj * T3;
                    vjl_xz += Al * T1;
                    break;
                    }
                }
            }
        }
        if (task_id >= ntasks) {
            break;
        }
        int ia = bas[ish*BAS_SLOTS+ATOM_OF];
        int ja = bas[jsh*BAS_SLOTS+ATOM_OF];
        int ka = bas[ksh*BAS_SLOTS+ATOM_OF];
        int la = bas[lsh*BAS_SLOTS+ATOM_OF];
        int natm = envs.natm;
        double *ejk = jk.ejk;
        atomicAdd(ejk + (ia*natm+ka)*9 + 0, vik_xx);
        atomicAdd(ejk + (ia*natm+ka)*9 + 1, vik_xy);
        atomicAdd(ejk + (ia*natm+ka)*9 + 2, vik_xz);
        atomicAdd(ejk + (ia*natm+ka)*9 + 3, vik_yx);
        atomicAdd(ejk + (ia*natm+ka)*9 + 4, vik_yy);
        atomicAdd(ejk + (ia*natm+ka)*9 + 5, vik_yz);
        atomicAdd(ejk + (ia*natm+ka)*9 + 6, vik_zx);
        atomicAdd(ejk + (ia*natm+ka)*9 + 7, vik_zy);
        atomicAdd(ejk + (ia*natm+ka)*9 + 8, vik_zz);
        atomicAdd(ejk + (ja*natm+ka)*9 + 0, vjk_xx);
        atomicAdd(ejk + (ja*natm+ka)*9 + 1, vjk_xy);
        atomicAdd(ejk + (ja*natm+ka)*9 + 2, vjk_xz);
        atomicAdd(ejk + (ja*natm+ka)*9 + 3, vjk_yx);
        atomicAdd(ejk + (ja*natm+ka)*9 + 4, vjk_yy);
        atomicAdd(ejk + (ja*natm+ka)*9 + 5, vjk_yz);
        atomicAdd(ejk + (ja*natm+ka)*9 + 6, vjk_zx);
        atomicAdd(ejk + (ja*natm+ka)*9 + 7, vjk_zy);
        atomicAdd(ejk + (ja*natm+ka)*9 + 8, vjk_zz);
        atomicAdd(ejk + (ia*natm+la)*9 + 0, vil_xx);
        atomicAdd(ejk + (ia*natm+la)*9 + 1, vil_xy);
        atomicAdd(ejk + (ia*natm+la)*9 + 2, vil_xz);
        atomicAdd(ejk + (ia*natm+la)*9 + 3, vil_yx);
        atomicAdd(ejk + (ia*natm+la)*9 + 4, vil_yy);
        atomicAdd(ejk + (ia*natm+la)*9 + 5, vil_yz);
        atomicAdd(ejk + (ia*natm+la)*9 + 6, vil_zx);
        atomicAdd(ejk + (ia*natm+la)*9 + 7, vil_zy);
        atomicAdd(ejk + (ia*natm+la)*9 + 8, vil_zz);
        atomicAdd(ejk + (ja*natm+la)*9 + 0, vjl_xx);
        atomicAdd(ejk + (ja*natm+la)*9 + 1, vjl_xy);
        atomicAdd(ejk + (ja*natm+la)*9 + 2, vjl_xz);
        atomicAdd(ejk + (ja*natm+la)*9 + 3, vjl_yx);
        atomicAdd(ejk + (ja*natm+la)*9 + 4, vjl_yy);
        atomicAdd(ejk + (ja*natm+la)*9 + 5, vjl_yz);
        atomicAdd(ejk + (ja*natm+la)*9 + 6, vjl_zx);
        atomicAdd(ejk + (ja*natm+la)*9 + 7, vjl_zy);
        atomicAdd(ejk + (ja*natm+la)*9 + 8, vjl_zz);
    }
}
}

// type12 (dp|ds): 108 outputs, 18 tuples per direction, 32 threads x 8 quartets per block, g_size 96
__global__ static
__launch_bounds__(256, 1)
void rys_ejk_ip2_type12_gen_2120(JKENERGY_KERNEL_ARGS)
{
    JKENERGY_KERNEL_SETUP();
    constexpr int nsq_per_block = 8;
    constexpr int gout_stride = 32;
    int t_id = gout_id * nsq_per_block + sq_id;
    int threads = nsq_per_block * gout_stride;
    int nbas = envs.nbas;
    int *bas = envs.bas;
    double *env = envs.env;
    int iprim = bounds.iprim;
    int jprim = bounds.jprim;
    int kprim = bounds.kprim;
    int lprim = bounds.lprim;
    int nroots = bounds.nroots;
    double *rlrk = shared_memory + sq_id;
    double *Rpq = shared_memory + nsq_per_block * 3 + sq_id;
    // the g arrays of the three directions, then the first-derivative factors of every tuple
    double *gx = shared_memory + nsq_per_block * 6 + sq_id;
    double *rw = shared_memory + nsq_per_block * 510 + sq_id;
    double *cicj_cache = shared_memory + nsq_per_block * (510+nroots*2);

    uint32_t *bas_kl_idx = pool + worker_id * QUEUE_DEPTH;
    double *dd_cache = dd_pool + worker_id * 872 + sq_id;
while (1) {
    __syncthreads();
    if (t_id == 0) {
        int task_id = atomicAdd(head, 1);
        int batch_kl = task_id / bounds.npairs_ij;
        pair_ij = task_id - bounds.npairs_ij * batch_kl;
        pair_kl0 = batch_kl * (QUEUE_DEPTH - 512);
        uint32_t bas_ij = bounds.pair_ij_mapping[pair_ij];
        ish = bas_ij / nbas;
        jsh = bas_ij % nbas;
    }
    __syncthreads();
    if (pair_kl0 >= bounds.npairs_kl) {
        break;
    }
    if (jk.lr_factor != 0) {
        _fill_ejk_tasks(ntasks, pair_kl0, bas_kl_idx, pair_ij, ish, jsh,
                        q_cond_ij, q_cond_kl,
                        (int *)shared_memory, jk, envs, bounds);
    } else {
        _fill_sr_ejk_tasks(ntasks, pair_kl0, bas_kl_idx, pair_ij, ish, jsh,
                           q_cond_ij, q_cond_kl,
                           s_cond_ij, s_cond_kl, diffuse_exps,
                           (int *)shared_memory, jk, envs, bounds);
    }
    if (ntasks == 0) {
        continue;
    }
    if (t_id == 0) {
        expi = bas[ish*BAS_SLOTS+PTR_EXP];
        expj = bas[jsh*BAS_SLOTS+PTR_EXP];
    }
    __syncthreads();
    if (t_id < 3) {
        int ri_ptr = bas[ish*BAS_SLOTS+PTR_BAS_COORD];
        int rj_ptr = bas[jsh*BAS_SLOTS+PTR_BAS_COORD];
        ri[t_id] = env[ri_ptr+t_id];
        rjri[t_id] = env[rj_ptr+t_id] - ri[t_id];
    }
    __syncthreads();
    double *ci = env + bas[ish*BAS_SLOTS+PTR_COEFF];
    double *cj = env + bas[jsh*BAS_SLOTS+PTR_COEFF];
    double xjxi = rjri[0];
    double yjyi = rjri[1];
    double zjzi = rjri[2];
    for (int ij = t_id; ij < iprim*jprim; ij += threads) {
        int ip = ij / jprim;
        int jp = ij % jprim;
        double ai = env[expi+ip];
        double aj = env[expj+jp];
        double aij = ai + aj;
        double theta_ij = ai * aj / aij;
        double rr_ij = xjxi*xjxi + yjyi*yjyi + zjzi*zjzi;
        double Kab = exp(-theta_ij * rr_ij);
        cicj_cache[ij] = ci[ip] * cj[jp] * Kab;
    }
    __syncthreads();

    int *ao_loc = envs.ao_loc;
    int nao = ao_loc[nbas];
    double *dm = jk.dm;
    double vij_xx = 0;
    double vij_xy = 0;
    double vij_xz = 0;
    double vij_yx = 0;
    double vij_yy = 0;
    double vij_yz = 0;
    double vij_zx = 0;
    double vij_zy = 0;
    double vij_zz = 0;
    double vii_xx = 0;
    double vii_xy = 0;
    double vii_xz = 0;
    double vii_yy = 0;
    double vii_yz = 0;
    double vii_zz = 0;
    double vjj_xx = 0;
    double vjj_xy = 0;
    double vjj_xz = 0;
    double vjj_yy = 0;
    double vjj_yz = 0;
    double vjj_zz = 0;
    for (int task_id = sq_id; task_id < ntasks+sq_id; task_id += nsq_per_block) {
        // another thread of this quartet may still read the previous task's dd_cache
        __syncthreads();
        uint32_t bas_kl = bas_kl_idx[task_id];
        int ksh = bas_kl / nbas;
        int lsh = bas_kl % nbas;
        double fac_sym = PI_FAC;
        if (task_id < ntasks) {
            if (ish == jsh) fac_sym *= .5;
            if (ksh == lsh) fac_sym *= .5;
            if (ish*nbas+jsh == bas_kl) fac_sym *= .5;
        } else {
            fac_sym = 0;
        }
        int i0 = ao_loc[ish];
        int j0 = ao_loc[jsh];
        int k0 = ao_loc[ksh];
        int l0 = ao_loc[lsh];
        int expk = bas[ksh*BAS_SLOTS+PTR_EXP];
        int expl = bas[lsh*BAS_SLOTS+PTR_EXP];
        int ck = bas[ksh*BAS_SLOTS+PTR_COEFF];
        int cl = bas[lsh*BAS_SLOTS+PTR_COEFF];
        int rk = bas[ksh*BAS_SLOTS+PTR_BAS_COORD];
        int rl = bas[lsh*BAS_SLOTS+PTR_BAS_COORD];
        double xlxk = env[rl+0] - env[rk+0];
        double ylyk = env[rl+1] - env[rk+1];
        double zlzk = env[rl+2] - env[rk+2];
        if (gout_id == 0) {
            rlrk[0] = xlxk;
            rlrk[8] = ylyk;
            rlrk[2*8] = zlzk;
        }
        double vkl_xx = 0;
        double vkl_xy = 0;
        double vkl_xz = 0;
        double vkl_yx = 0;
        double vkl_yy = 0;
        double vkl_yz = 0;
        double vkl_zx = 0;
        double vkl_zy = 0;
        double vkl_zz = 0;
        double vkk_xx = 0;
        double vkk_xy = 0;
        double vkk_xz = 0;
        double vkk_yy = 0;
        double vkk_yz = 0;
        double vkk_zz = 0;
        double vll_xx = 0;
        double vll_xy = 0;
        double vll_xz = 0;
        double vll_yy = 0;
        double vll_yz = 0;
        double vll_zz = 0;
        int do_j = jk.j_factor != 0.;
        int do_k = jk.k_factor != 0.;
        if (jk.n_dm == 1) {
            for (int n = gout_id; n < 108; n+=32) {
                int i = n % 6;
                int j = n / 6 % 3;
                int k = n / 18 % 6;
                int l = n / 108;
                int _i = i + i0;
                int _j = j + j0;
                int _k = k + k0;
                int _l = l + l0;
                int _jl = _j*nao+_l;
                int _jk = _j*nao+_k;
                int _il = _i*nao+_l;
                int _ik = _i*nao+_k;
                int _ji = _j*nao+_i;
                int _lk = _l*nao+_k;
                double dd = 0;
                if (do_k) {
                    dd += jk.k_factor * (dm[_jk] * dm[_il] + dm[_jl] * dm[_ik]);
                }
                if (do_j) {
                    dd += jk.j_factor * dm[_ji] * dm[_lk];
                }
                dd_cache[n*8] = fac_sym * dd;
            }
        } else {
            double *dmb = dm + nao * nao;
            for (int n = gout_id; n < 108; n+=32) {
                int i = n % 6;
                int j = n / 6 % 3;
                int k = n / 18 % 6;
                int l = n / 108;
                int _i = i + i0;
                int _j = j + j0;
                int _k = k + k0;
                int _l = l + l0;
                int _jl = _j*nao+_l;
                int _jk = _j*nao+_k;
                int _il = _i*nao+_l;
                int _ik = _i*nao+_k;
                int _ji = _j*nao+_i;
                int _lk = _l*nao+_k;
                double dd = 0;
                if (do_k) {
                    dd += dm [_jk] * dm [_il] + dm [_jl] * dm [_ik];
                    dd += dmb[_jk] * dmb[_il] + dmb[_jl] * dmb[_ik];
                    dd *= jk.k_factor;
                }
                if (do_j) {
                    dd += jk.j_factor * (dm[_ji] + dmb[_ji]) * (dm[_lk] + dmb[_lk]);
                }
                dd_cache[n*8] = fac_sym * dd;
            }
        }
        if (gout_id == 0) {
            dd_cache[864] = 0;
        }
        for (int klp = 0; klp < kprim*lprim; ++klp) {
            int kp = klp / lprim;
            int lp = klp % lprim;
            double ak = env[expk+kp];
            double al = env[expl+lp];
            double ak2 = ak * 2;
            double al2 = al * 2;
            double akl = ak + al;
            double al_akl = al / akl;
            double theta_kl = ak * al_akl;
            __syncthreads();
            if (gout_id == 0) {
                double Kcd = exp(-theta_kl * (xlxk*xlxk+ylyk*ylyk+zlzk*zlzk));
                double ckcl = env[ck+kp] * env[cl+lp] * Kcd;
                gx[0] = ckcl;
            }
            for (int ijp = 0; ijp < iprim*jprim; ++ijp) {
                if (fabs(cicj_cache[ijp]) < PRIM_CUTOFF) continue;
                int ip = ijp / jprim;
                int jp = ijp % jprim;
                double ai = env[expi+ip];
                double aj = env[expj+jp];
                double ai2 = ai * 2;
                double aj2 = aj * 2;
                double aij = ai + aj;
                double aj_aij = aj / aij;
                double xij = ri[0] + rjri[0] * aj_aij;
                double yij = ri[1] + rjri[1] * aj_aij;
                double zij = ri[2] + rjri[2] * aj_aij;
                double xkl = env[rk+0] + xlxk * al_akl;
                double ykl = env[rk+1] + ylyk * al_akl;
                double zkl = env[rk+2] + zlzk * al_akl;
                double xpq = xij - xkl;
                double ypq = yij - ykl;
                double zpq = zij - zkl;
                double theta = aij * akl / (aij + akl);
                double rr = xpq * xpq + ypq * ypq + zpq * zpq;
                __syncthreads();
                if (gout_id == 0) {
                    Rpq[0] = xpq;
                    Rpq[8] = ypq;
                    Rpq[2*8] = zpq;
                    double cicj = cicj_cache[ijp];
                    gx[96*8] = cicj / (aij*akl*sqrt(aij+akl));
                }
                rys_roots_for_k(nroots, theta, rr, rw, jk.omega, jk.lr_factor, jk.sr_factor, nsq_per_block, 32, gout_id);
                for (int irys = 0; irys < nroots; ++irys) {
                    __syncthreads();
                    double s0, s1, s2;
                    double rt = rw[irys*16];
                    double rt_aa = rt / (aij + akl);
                    double rt_aij = rt_aa * akl;
                    double rt_akl = rt_aa * aij;
                    double b10 = .5/aij * (1 - rt_aij);
                    double b00 = .5 * rt_aa;
                    double b01 = .5/akl * (1 - rt_akl);
                    for (int n = gout_id; n < 3; n += 32) {
                        if (n == 2) {
                            gx[1536] = rw[irys*16+8];
                        }
                        double *_gx = gx + n * 768;
                        double xjxi = rjri[n];
                        double Rpa = xjxi * aj_aij;
                        double c0x = Rpa - rt_aij * Rpq[n*8];
                        s0 = _gx[0];
                        s1 = c0x * s0;
                        _gx[8] = s1;
                        s2 = c0x * s1 + 1 * b10 * s0;
                        _gx[16] = s2;
                        s0 = s1;
                        s1 = s2;
                        s2 = c0x * s1 + 2 * b10 * s0;
                        _gx[24] = s2;
                        s0 = s1;
                        s1 = s2;
                        s2 = c0x * s1 + 3 * b10 * s0;
                        _gx[32] = s2;
                        s0 = s1;
                        s1 = s2;
                        s2 = c0x * s1 + 4 * b10 * s0;
                        _gx[40] = s2;
                        double xlxk = rlrk[n*8];
                        double Rqc = xlxk * al_akl;
                        double cpx = Rqc + rt_akl * Rpq[n*8];
                        s0 = _gx[0];
                        s1 = cpx * s0;
                        _gx[96] = s1;
                        s2 = cpx*s1 + 1 * b01 *s0;
                        _gx[192] = s2;
                        s0 = s1;
                        s1 = s2;
                        s2 = cpx*s1 + 2 * b01 *s0;
                        _gx[288] = s2;
                        s0 = s1;
                        s1 = s2;
                        s2 = cpx*s1 + 3 * b01 *s0;
                        _gx[384] = s2;
                        s0 = _gx[8];
                        s1 = cpx * s0;
                        s1 += 1 * b00 * _gx[0];
                        _gx[104] = s1;
                        s2 = cpx*s1 + 1 * b01 *s0;
                        s2 += 1 * b00 * _gx[96];
                        _gx[200] = s2;
                        s0 = s1;
                        s1 = s2;
                        s2 = cpx*s1 + 2 * b01 *s0;
                        s2 += 1 * b00 * _gx[192];
                        _gx[296] = s2;
                        s0 = s1;
                        s1 = s2;
                        s2 = cpx*s1 + 3 * b01 *s0;
                        s2 += 1 * b00 * _gx[288];
                        _gx[392] = s2;
                        s0 = _gx[16];
                        s1 = cpx * s0;
                        s1 += 2 * b00 * _gx[8];
                        _gx[112] = s1;
                        s2 = cpx*s1 + 1 * b01 *s0;
                        s2 += 2 * b00 * _gx[104];
                        _gx[208] = s2;
                        s0 = s1;
                        s1 = s2;
                        s2 = cpx*s1 + 2 * b01 *s0;
                        s2 += 2 * b00 * _gx[200];
                        _gx[304] = s2;
                        s0 = s1;
                        s1 = s2;
                        s2 = cpx*s1 + 3 * b01 *s0;
                        s2 += 2 * b00 * _gx[296];
                        _gx[400] = s2;
                        s0 = _gx[24];
                        s1 = cpx * s0;
                        s1 += 3 * b00 * _gx[16];
                        _gx[120] = s1;
                        s2 = cpx*s1 + 1 * b01 *s0;
                        s2 += 3 * b00 * _gx[112];
                        _gx[216] = s2;
                        s0 = s1;
                        s1 = s2;
                        s2 = cpx*s1 + 2 * b01 *s0;
                        s2 += 3 * b00 * _gx[208];
                        _gx[312] = s2;
                        s0 = s1;
                        s1 = s2;
                        s2 = cpx*s1 + 3 * b01 *s0;
                        s2 += 3 * b00 * _gx[304];
                        _gx[408] = s2;
                        s0 = _gx[32];
                        s1 = cpx * s0;
                        s1 += 4 * b00 * _gx[24];
                        _gx[128] = s1;
                        s2 = cpx*s1 + 1 * b01 *s0;
                        s2 += 4 * b00 * _gx[120];
                        _gx[224] = s2;
                        s0 = s1;
                        s1 = s2;
                        s2 = cpx*s1 + 2 * b01 *s0;
                        s2 += 4 * b00 * _gx[216];
                        _gx[320] = s2;
                        s0 = s1;
                        s1 = s2;
                        s2 = cpx*s1 + 3 * b01 *s0;
                        s2 += 4 * b00 * _gx[312];
                        _gx[416] = s2;
                        s0 = _gx[40];
                        s1 = cpx * s0;
                        s1 += 5 * b00 * _gx[32];
                        _gx[136] = s1;
