        double vjk_xx = 0;
        double vjk_xy = 0;
        double vjk_xz = 0;
        double vjk_yx = 0;
        double vjk_yy = 0;
        double vjk_yz = 0;
        double vjk_zx = 0;
        double vjk_zy = 0;
        double vjk_zz = 0;
