while (1) {
    __syncthreads();
    if (t_id == 0) {
        int task_id = atomicAdd(head, 1);
        int batch_kl = task_id / bounds.npairs_ij;
        pair_ij = task_id - bounds.npairs_ij * batch_kl;
        pair_kl0 = batch_kl * (QUEUE_DEPTH - 512);
        uint32_t bas_ij = bounds.pair_ij_mapping[pair_ij];
        ish = bas_ij / nbas;
        jsh = bas_ij % nbas;
    }
    __syncthreads();
    if (pair_kl0 >= bounds.npairs_kl) {
        break;
    }
    if (jk.lr_factor != 0) {
        _fill_ejk_tasks(ntasks, pair_kl0, bas_kl_idx, pair_ij, ish, jsh,
                        q_cond_ij, q_cond_kl,
                        (int *)shared_memory, jk, envs, bounds);
    } else {
        _fill_sr_ejk_tasks(ntasks, pair_kl0, bas_kl_idx, pair_ij, ish, jsh,
                           q_cond_ij, q_cond_kl,
                           s_cond_ij, s_cond_kl, diffuse_exps,
                           (int *)shared_memory, jk, envs, bounds);
    }
    if (ntasks == 0) {
        continue;
    }
    if (t_id == 0) {
        expi = bas[ish*BAS_SLOTS+PTR_EXP];
        expj = bas[jsh*BAS_SLOTS+PTR_EXP];
    }
    __syncthreads();
    if (t_id < 3) {
        int ri_ptr = bas[ish*BAS_SLOTS+PTR_BAS_COORD];
        int rj_ptr = bas[jsh*BAS_SLOTS+PTR_BAS_COORD];
        ri[t_id] = env[ri_ptr+t_id];
        rjri[t_id] = env[rj_ptr+t_id] - ri[t_id];
    }
    __syncthreads();
    double *ci = env + bas[ish*BAS_SLOTS+PTR_COEFF];
    double *cj = env + bas[jsh*BAS_SLOTS+PTR_COEFF];
    double xjxi = rjri[0];
    double yjyi = rjri[1];
    double zjzi = rjri[2];
    for (int ij = t_id; ij < iprim*jprim; ij += threads) {
        int ip = ij / jprim;
        int jp = ij % jprim;
        double ai = env[expi+ip];
        double aj = env[expj+jp];
        double aij = ai + aj;
        double theta_ij = ai * aj / aij;
        double rr_ij = xjxi*xjxi + yjyi*yjyi + zjzi*zjzi;
        double Kab = exp(-theta_ij * rr_ij);
        cicj_cache[ij] = ci[ip] * cj[jp] * Kab;
    }
    __syncthreads();

    int *ao_loc = envs.ao_loc;
    int nao = ao_loc[nbas];
    double *dm = jk.dm;
    double vij_xx = 0;
    double vij_xy = 0;
    double vij_xz = 0;
    double vij_yx = 0;
    double vij_yy = 0;
    double vij_yz = 0;
    double vij_zx = 0;
    double vij_zy = 0;
    double vij_zz = 0;
    double vii_xx = 0;
    double vii_xy = 0;
    double vii_xz = 0;
    double vii_yy = 0;
    double vii_yz = 0;
    double vii_zz = 0;
    double vjj_xx = 0;
    double vjj_xy = 0;
    double vjj_xz = 0;
    double vjj_yy = 0;
    double vjj_yz = 0;
    double vjj_zz = 0;
    for (int task_id = sq_id; task_id < ntasks+sq_id; task_id += nsq_per_block) {
        // another thread of this quartet may still read the previous task's dd_cache
        __syncthreads();
        uint32_t bas_kl = bas_kl_idx[task_id];
        int ksh = bas_kl / nbas;
        int lsh = bas_kl % nbas;
        double fac_sym = PI_FAC;
        if (task_id < ntasks) {
            if (ish == jsh) fac_sym *= .5;
            if (ksh == lsh) fac_sym *= .5;
            if (ish*nbas+jsh == bas_kl) fac_sym *= .5;
        } else {
            fac_sym = 0;
        }
        int i0 = ao_loc[ish];
        int j0 = ao_loc[jsh];
        int k0 = ao_loc[ksh];
        int l0 = ao_loc[lsh];
        int expk = bas[ksh*BAS_SLOTS+PTR_EXP];
        int expl = bas[lsh*BAS_SLOTS+PTR_EXP];
        int ck = bas[ksh*BAS_SLOTS+PTR_COEFF];
        int cl = bas[lsh*BAS_SLOTS+PTR_COEFF];
        int rk = bas[ksh*BAS_SLOTS+PTR_BAS_COORD];
        int rl = bas[lsh*BAS_SLOTS+PTR_BAS_COORD];
        double xlxk = env[rl+0] - env[rk+0];
        double ylyk = env[rl+1] - env[rk+1];
        double zlzk = env[rl+2] - env[rk+2];
        if (gout_id == 0) {
            rlrk[0] = xlxk;
            rlrk[32] = ylyk;
            rlrk[2*32] = zlzk;
        }
        double vkl_xx = 0;
        double vkl_xy = 0;
        double vkl_xz = 0;
        double vkl_yx = 0;
        double vkl_yy = 0;
        double vkl_yz = 0;
        double vkl_zx = 0;
        double vkl_zy = 0;
        double vkl_zz = 0;
        double vkk_xx = 0;
        double vkk_xy = 0;
        double vkk_xz = 0;
        double vkk_yy = 0;
        double vkk_yz = 0;
        double vkk_zz = 0;
        double vll_xx = 0;
        double vll_xy = 0;
        double vll_xz = 0;
        double vll_yy = 0;
        double vll_yz = 0;
        double vll_zz = 0;
        int do_j = jk.j_factor != 0.;
        int do_k = jk.k_factor != 0.;
        if (jk.n_dm == 1) {
            for (int n = gout_id; n < 18; n+=8) {
                int i = n % 6;
                int j = n / 6 % 1;
                int k = n / 6 % 3;
                int l = n / 18;
                int _i = i + i0;
                int _j = j + j0;
                int _k = k + k0;
                int _l = l + l0;
                int _jl = _j*nao+_l;
                int _jk = _j*nao+_k;
                int _il = _i*nao+_l;
                int _ik = _i*nao+_k;
                int _ji = _j*nao+_i;
                int _lk = _l*nao+_k;
                double dd = 0;
                if (do_k) {
                    dd += jk.k_factor * (dm[_jk] * dm[_il] + dm[_jl] * dm[_ik]);
                }
                if (do_j) {
                    dd += jk.j_factor * dm[_ji] * dm[_lk];
                }
                dd_cache[n*32] = fac_sym * dd;
            }
        } else {
            double *dmb = dm + nao * nao;
            for (int n = gout_id; n < 18; n+=8) {
                int i = n % 6;
                int j = n / 6 % 1;
                int k = n / 6 % 3;
                int l = n / 18;
                int _i = i + i0;
                int _j = j + j0;
                int _k = k + k0;
                int _l = l + l0;
                int _jl = _j*nao+_l;
                int _jk = _j*nao+_k;
                int _il = _i*nao+_l;
                int _ik = _i*nao+_k;
                int _ji = _j*nao+_i;
                int _lk = _l*nao+_k;
                double dd = 0;
                if (do_k) {
                    dd += dm [_jk] * dm [_il] + dm [_jl] * dm [_ik];
                    dd += dmb[_jk] * dmb[_il] + dmb[_jl] * dmb[_ik];
                    dd *= jk.k_factor;
                }
                if (do_j) {
                    dd += jk.j_factor * (dm[_ji] + dmb[_ji]) * (dm[_lk] + dmb[_lk]);
                }
                dd_cache[n*32] = fac_sym * dd;
            }
        }
        for (int klp = 0; klp < kprim*lprim; ++klp) {
            int kp = klp / lprim;
            int lp = klp % lprim;
            double ak = env[expk+kp];
            double al = env[expl+lp];
            double ak2 = ak * 2;
            double al2 = al * 2;
            double akl = ak + al;
            double al_akl = al / akl;
            double theta_kl = ak * al_akl;
            __syncthreads();
            if (gout_id == 0) {
                double Kcd = exp(-theta_kl * (xlxk*xlxk+ylyk*ylyk+zlzk*zlzk));
                double ckcl = env[ck+kp] * env[cl+lp] * Kcd;
                gx[0] = ckcl;
            }
            for (int ijp = 0; ijp < iprim*jprim; ++ijp) {
                if (fabs(cicj_cache[ijp]) < PRIM_CUTOFF) continue;
                int ip = ijp / jprim;
                int jp = ijp % jprim;
                double ai = env[expi+ip];
                double aj = env[expj+jp];
                double ai2 = ai * 2;
                double aj2 = aj * 2;
                double aij = ai + aj;
                double aj_aij = aj / aij;
                double xij = ri[0] + rjri[0] * aj_aij;
                double yij = ri[1] + rjri[1] * aj_aij;
                double zij = ri[2] + rjri[2] * aj_aij;
                double xkl = env[rk+0] + xlxk * al_akl;
                double ykl = env[rk+1] + ylyk * al_akl;
                double zkl = env[rk+2] + zlzk * al_akl;
                double xpq = xij - xkl;
                double ypq = yij - ykl;
                double zpq = zij - zkl;
                double theta = aij * akl / (aij + akl);
                double rr = xpq * xpq + ypq * ypq + zpq * zpq;
                __syncthreads();
                if (gout_id == 0) {
                    Rpq[0] = xpq;
                    Rpq[32] = ypq;
                    Rpq[2*32] = zpq;
                    double cicj = cicj_cache[ijp];
                    gx[48*32] = cicj / (aij*akl*sqrt(aij+akl));
                }
                rys_roots_for_k(nroots, theta, rr, rw, jk.omega, jk.lr_factor, jk.sr_factor, nsq_per_block, 8, gout_id);
                for (int irys = 0; irys < nroots; ++irys) {
                    __syncthreads();
                    double s0, s1, s2;
                    double rt = rw[irys*64];
                    double rt_aa = rt / (aij + akl);
                    double rt_aij = rt_aa * akl;
                    double rt_akl = rt_aa * aij;
                    double b10 = .5/aij * (1 - rt_aij);
                    double b00 = .5 * rt_aa;
                    double b01 = .5/akl * (1 - rt_akl);
                    for (int n = gout_id; n < 3; n += 8) {
                        if (n == 2) {
                            gx[3072] = rw[irys*64+32];
                        }
                        double *_gx = gx + n * 1536;
                        double xjxi = rjri[n];
                        double Rpa = xjxi * aj_aij;
                        double c0x = Rpa - rt_aij * Rpq[n*32];
                        s0 = _gx[0];
                        s1 = c0x * s0;
                        _gx[32] = s1;
                        s2 = c0x * s1 + 1 * b10 * s0;
                        _gx[64] = s2;
                        s0 = s1;
                        s1 = s2;
                        s2 = c0x * s1 + 2 * b10 * s0;
                        _gx[96] = s2;
                        s0 = s1;
                        s1 = s2;
                        s2 = c0x * s1 + 3 * b10 * s0;
                        _gx[128] = s2;
                        double xlxk = rlrk[n*32];
                        double Rqc = xlxk * al_akl;
                        double cpx = Rqc + rt_akl * Rpq[n*32];
                        s0 = _gx[0];
                        s1 = cpx * s0;
                        _gx[256] = s1;
                        s2 = cpx*s1 + 1 * b01 *s0;
                        _gx[512] = s2;
                        s0 = s1;
                        s1 = s2;
                        s2 = cpx*s1 + 2 * b01 *s0;
                        _gx[768] = s2;
                        s0 = _gx[32];
                        s1 = cpx * s0;
                        s1 += 1 * b00 * _gx[0];
                        _gx[288] = s1;
                        s2 = cpx*s1 + 1 * b01 *s0;
                        s2 += 1 * b00 * _gx[256];
                        _gx[544] = s2;
                        s0 = s1;
                        s1 = s2;
                        s2 = cpx*s1 + 2 * b01 *s0;
                        s2 += 1 * b00 * _gx[512];
                        _gx[800] = s2;
                        s0 = _gx[64];
                        s1 = cpx * s0;
                        s1 += 2 * b00 * _gx[32];
                        _gx[320] = s1;
                        s2 = cpx*s1 + 1 * b01 *s0;
                        s2 += 2 * b00 * _gx[288];
                        _gx[576] = s2;
                        s0 = s1;
                        s1 = s2;
                        s2 = cpx*s1 + 2 * b01 *s0;
                        s2 += 2 * b00 * _gx[544];
                        _gx[832] = s2;
                        s0 = _gx[96];
                        s1 = cpx * s0;
                        s1 += 3 * b00 * _gx[64];
                        _gx[352] = s1;
                        s2 = cpx*s1 + 1 * b01 *s0;
                        s2 += 3 * b00 * _gx[320];
                        _gx[608] = s2;
                        s0 = s1;
                        s1 = s2;
                        s2 = cpx*s1 + 2 * b01 *s0;
                        s2 += 3 * b00 * _gx[576];
                        _gx[864] = s2;
                        s0 = _gx[128];
                        s1 = cpx * s0;
                        s1 += 4 * b00 * _gx[96];
                        _gx[384] = s1;
                        s2 = cpx*s1 + 1 * b01 *s0;
                        s2 += 4 * b00 * _gx[352];
                        _gx[640] = s2;
                        s0 = s1;
                        s1 = s2;
                        s2 = cpx*s1 + 2 * b01 *s0;
                        s2 += 4 * b00 * _gx[608];
                        _gx[896] = s2;
                        s1 = _gx[128];
                        s0 = _gx[96];
                        _gx[224] = s1 - xjxi * s0;
                        s1 = s0;
                        s0 = _gx[64];
                        _gx[192] = s1 - xjxi * s0;
                        s1 = s0;
                        s0 = _gx[32];
                        _gx[160] = s1 - xjxi * s0;
                        s1 = s0;
                        s0 = _gx[0];
                        _gx[128] = s1 - xjxi * s0;
                        s1 = s0;
                        s1 = _gx[384];
                        s0 = _gx[352];
                        _gx[480] = s1 - xjxi * s0;
                        s1 = s0;
                        s0 = _gx[320];
                        _gx[448] = s1 - xjxi * s0;
                        s1 = s0;
                        s0 = _gx[288];
                        _gx[416] = s1 - xjxi * s0;
                        s1 = s0;
                        s0 = _gx[256];
                        _gx[384] = s1 - xjxi * s0;
                        s1 = s0;
                        s1 = _gx[640];
                        s0 = _gx[608];
                        _gx[736] = s1 - xjxi * s0;
                        s1 = s0;
                        s0 = _gx[576];
                        _gx[704] = s1 - xjxi * s0;
                        s1 = s0;
                        s0 = _gx[544];
                        _gx[672] = s1 - xjxi * s0;
                        s1 = s0;
                        s0 = _gx[512];
                        _gx[640] = s1 - xjxi * s0;
                        s1 = s0;
                        s1 = _gx[896];
                        s0 = _gx[864];
                        _gx[992] = s1 - xjxi * s0;
                        s1 = s0;
                        s0 = _gx[832];
                        _gx[960] = s1 - xjxi * s0;
                        s1 = s0;
                        s0 = _gx[800];
                        _gx[928] = s1 - xjxi * s0;
                        s1 = s0;
                        s0 = _gx[768];
                        _gx[896] = s1 - xjxi * s0;
                        s1 = s0;
                        s1 = _gx[768];
                        s0 = _gx[512];
                        _gx[1280] = s1 - xlxk * s0;
                        s1 = s0;
                        s0 = _gx[256];
                        _gx[1024] = s1 - xlxk * s0;
                        s1 = s0;
                        s0 = _gx[0];
                        _gx[768] = s1 - xlxk * s0;
                        s1 = s0;
                        s1 = _gx[800];
                        s0 = _gx[544];
                        _gx[1312] = s1 - xlxk * s0;
                        s1 = s0;
                        s0 = _gx[288];
                        _gx[1056] = s1 - xlxk * s0;
                        s1 = s0;
                        s0 = _gx[32];
                        _gx[800] = s1 - xlxk * s0;
                        s1 = s0;
                        s1 = _gx[832];
                        s0 = _gx[576];
                        _gx[1344] = s1 - xlxk * s0;
                        s1 = s0;
                        s0 = _gx[320];
                        _gx[1088] = s1 - xlxk * s0;
                        s1 = s0;
                        s0 = _gx[64];
                        _gx[832] = s1 - xlxk * s0;
                        s1 = s0;
                        s1 = _gx[864];
                        s0 = _gx[608];
                        _gx[1376] = s1 - xlxk * s0;
                        s1 = s0;
                        s0 = _gx[352];
                        _gx[1120] = s1 - xlxk * s0;
                        s1 = s0;
                        s0 = _gx[96];
                        _gx[864] = s1 - xlxk * s0;
                        s1 = s0;
                        s1 = _gx[896];
                        s0 = _gx[640];
                        _gx[1408] = s1 - xlxk * s0;
                        s1 = s0;
                        s0 = _gx[384];
                        _gx[1152] = s1 - xlxk * s0;
                        s1 = s0;
                        s0 = _gx[128];
                        _gx[896] = s1 - xlxk * s0;
                        s1 = s0;
                        s1 = _gx[928];
                        s0 = _gx[672];
                        _gx[1440] = s1 - xlxk * s0;
                        s1 = s0;
                        s0 = _gx[416];
                        _gx[1184] = s1 - xlxk * s0;
                        s1 = s0;
                        s0 = _gx[160];
                        _gx[928] = s1 - xlxk * s0;
                        s1 = s0;
                        s1 = _gx[960];
                        s0 = _gx[704];
                        _gx[1472] = s1 - xlxk * s0;
                        s1 = s0;
                        s0 = _gx[448];
                        _gx[1216] = s1 - xlxk * s0;
                        s1 = s0;
                        s0 = _gx[192];
                        _gx[960] = s1 - xlxk * s0;
                        s1 = s0;
                        s1 = _gx[992];
                        s0 = _gx[736];
                        _gx[1504] = s1 - xlxk * s0;
                        s1 = s0;
                        s0 = _gx[480];
                        _gx[1248] = s1 - xlxk * s0;
                        s1 = s0;
                        s0 = _gx[224];
                        _gx[992] = s1 - xlxk * s0;
                        s1 = s0;
                    }
                    __syncthreads();
                    for (int e = gout_id; e < 18; e += 8) {
                        int d = e / 6;
                        int t = e - d * 6;
                        int ti = t % 3;
                        int tj = t / 3 % 1;
                        int tk = t / 3 % 2;
                        int tl = t / 6;
                        double *_g = gx + (d * 48 + ti + tj * 4 + tk * 8 + tl * 24) * 32;
                        double *_t = gx + (144 + e * 4) * 32;
                        _t[0] = ai2 * _g[32] - (ti ? ti * _g[-32] : 0.);
                        _t[32] = aj2 * _g[128] - (tj ? tj * _g[-128] : 0.);
                        _t[64] = ak2 * _g[256] - (tk ? tk * _g[-256] : 0.);
                        _t[96] = al2 * _g[768] - (tl ? tl * _g[-768] : 0.);
                    }
                    __syncthreads();
                    volatile double *vgx = gx;
                    double w, S, T0, T1, T2, T3, Ai, Aj, Ak, Al;
                    switch (gout_id / 1) {
                    case 0:
                    w = dd_cache[288] * vgx[3072];
                    S = w * vgx[1856];
                    T0 = vgx[6016] * w;
                    T1 = vgx[6048] * w;
                    T2 = vgx[6080] * w;
                    T3 = vgx[6112] * w;
                    w = dd_cache[320] * vgx[3104];
                    S += w * vgx[1824];
                    T0 += vgx[5888] * w;
                    T1 += vgx[5920] * w;
                    T2 += vgx[5952] * w;
                    T3 += vgx[5984] * w;
                    w = dd_cache[352] * vgx[3136];
                    S += w * vgx[1792];
                    T0 += vgx[5760] * w;
                    T1 += vgx[5792] * w;
                    T2 += vgx[5824] * w;
                    T3 += vgx[5856] * w;
                    w = dd_cache[480] * vgx[3328];
                    S += w * vgx[1600];
                    T0 += vgx[5632] * w;
                    T1 += vgx[5664] * w;
                    T2 += vgx[5696] * w;
                    T3 += vgx[5728] * w;
                    w = dd_cache[512] * vgx[3360];
                    S += w * vgx[1568];
                    T0 += vgx[5504] * w;
                    T1 += vgx[5536] * w;
                    T2 += vgx[5568] * w;
                    T3 += vgx[5600] * w;
                    w = dd_cache[544] * vgx[3392];
                    S += w * vgx[1536];
                    T0 += vgx[5376] * w;
                    T1 += vgx[5408] * w;
                    T2 += vgx[5440] * w;
                    T3 += vgx[5472] * w;
                    Ai = vgx[4608];
                    Aj = vgx[4640];
                    Ak = vgx[4672];
                    Al = vgx[4704];
                    vii_xx += (ai2 * (ai2 * (vgx[160] + xjxi * vgx[32]) - 1.0 * vgx[0])) * S;
                    vjj_xx += (aj2 * (aj2 * (vgx[160] - xjxi * vgx[128]) - 1.0 * vgx[0])) * S;
                    vij_xx += (aj2 * (ai2 * vgx[160])) * S;
                    vkk_xx += (ak2 * (ak2 * (vgx[1024] + xlxk * vgx[256]) - 1.0 * vgx[0])) * S;
                    vll_xx += (al2 * (al2 * (vgx[1024] - xlxk * vgx[768]) - 1.0 * vgx[0])) * S;
                    vkl_xx += (al2 * (ak2 * vgx[1024])) * S;
                    vij_xy += Ai * T1;
                    vij_yx += Aj * T0;
                    vjj_xy += Aj * T1;
                    vii_xy += Ai * T0;
                    vkl_xy += Ak * T3;
                    vkl_yx += Al * T2;
                    vll_xy += Al * T3;
                    vkk_xy += Ak * T2;
                    w = dd_cache[0] * vgx[320];
                    S = w * vgx[3072];
                    T0 = vgx[6144] * w;
                    T1 = vgx[6176] * w;
                    T2 = vgx[6208] * w;
                    T3 = vgx[6240] * w;
                    w = dd_cache[64] * vgx[288];
                    S += w * vgx[3104];
                    T0 += vgx[6272] * w;
                    T1 += vgx[6304] * w;
                    T2 += vgx[6336] * w;
                    T3 += vgx[6368] * w;
                    w = dd_cache[160] * vgx[256];
                    S += w * vgx[3136];
