                    vjj_yy += (aj2 * (aj2 * (vgx[1760] - yjyi * vgx[1728]) - 1.0 * vgx[1600])) * S;
                    vij_yy += (aj2 * (ai2 * vgx[1760] - 2.0 * vgx[1696])) * S;
