                    vii_zz += (ai2 * (ai2 * (vgx[3296] + zjzi * vgx[3168]) - 5.0 * vgx[3136]) + 2.0 * vgx[3072]) * S;
                    vjj_zz += (aj2 * (aj2 * (vgx[3296] - zjzi * vgx[3264]) - 1.0 * vgx[3136])) * S;
                    vij_zz += (aj2 * (ai2 * vgx[3296] - 2.0 * vgx[3232])) * S;
                    vkk_zz += (ak2 * (ak2 * (vgx[4160] + zlzk * vgx[3392]) - 1.0 * vgx[3136])) * S;
