                    vij_xx += (aj2 * (ai2 * vgx[480] - 2.0 * vgx[416])) * S;
                    vkk_xx += (ak2 * (ak2 * (vgx[1344] + xlxk * vgx[576]) - 3.0 * vgx[320])) * S;
                    vll_xx += (al2 * (al2 * (vgx[1344] - xlxk * vgx[1088]) - 1.0 * vgx[320])) * S;
                    vkl_xx += (al2 * (ak2 * vgx[1344] - 1.0 * vgx[832])) * S;
                    vij_xy += Ai * T1;
                    vij_yx += Aj * T0;
                    vjj_xy += Aj * T1;
                    vii_xy += Ai * T0;
                    vkl_xy += Ak * T3;
