                    vii_yy += (ai2 * (ai2 * (vgx[2016] + yjyi * vgx[1888]) - 5.0 * vgx[1856]) + 2.0 * vgx[1792]) * S;
                    vjj_yy += (aj2 * (aj2 * (vgx[2016] - yjyi * vgx[1984]) - 1.0 * vgx[1856])) * S;
                    vij_yy += (aj2 * (ai2 * vgx[2016] - 2.0 * vgx[1952])) * S;
                    vkk_yy += (ak2 * (ak2 * (vgx[2880] + ylyk * vgx[2112]) - 3.0 * vgx[1856])) * S;
                    vll_yy += (al2 * (al2 * (vgx[2880] - ylyk * vgx[2624]) - 1.0 * vgx[1856])) * S;
                    vkl_yy += (al2 * (ak2 * vgx[2880] - 1.0 * vgx[2368])) * S;
                    vij_yz += Ai * T1;
