                    Ai = vgx[6784];
                    Aj = vgx[6816];
                    Ak = vgx[6848];
                    Al = vgx[6880];
                    vii_zz += (ai2 * (ai2 * (vgx[3552] + zjzi * vgx[3424]) - 5.0 * vgx[3392]) + 2.0 * vgx[3328]) * S;
                    vjj_zz += (aj2 * (aj2 * (vgx[3552] - zjzi * vgx[3520]) - 1.0 * vgx[3392])) * S;
                    vij_zz += (aj2 * (ai2 * vgx[3552] - 2.0 * vgx[3488])) * S;
                    vkk_zz += (ak2 * (ak2 * (vgx[4416] + zlzk * vgx[3648]) - 3.0 * vgx[3392])) * S;
                    vll_zz += (al2 * (al2 * (vgx[4416] - zlzk * vgx[4160]) - 1.0 * vgx[3392])) * S;
                    vkl_zz += (al2 * (ak2 * vgx[4416] - 1.0 * vgx[3904])) * S;
                    vij_zx += Ai * T1;
                    vij_xz += Aj * T0;
                    vjj_xz += Aj * T1;
                    vii_xz += Ai * T0;
                    vkl_zx += Ak * T3;
